import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def extract_table_cells_and_rows(document_path: str) -> Dict[str, Any]:
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint:
        raise ValueError("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT is required")
    if not key:
        raise ValueError("AZURE_DOCUMENT_INTELLIGENCE_KEY is required")

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-layout",
            body=f,
        )
    result = poller.result()

    tables_output: List[Dict[str, Any]] = []

    for table_idx, table in enumerate(getattr(result, "tables", []) or []):
        cells_by_row: Dict[int, List[Dict[str, Any]]] = {}

        for cell in getattr(table, "cells", []) or []:
            row_index = int(getattr(cell, "row_index", 0))
            col_index = int(getattr(cell, "column_index", 0))
            cell_data = {
                "row_index": row_index,
                "column_index": col_index,
                "row_span": int(getattr(cell, "row_span", 1) or 1),
                "column_span": int(getattr(cell, "column_span", 1) or 1),
                "text": getattr(cell, "content", "") or "",
                "kind": getattr(cell, "kind", None),
            }
            cells_by_row.setdefault(row_index, []).append(cell_data)

        rows: List[Dict[str, Any]] = []
        for row_index in sorted(cells_by_row.keys()):
            row_cells = sorted(cells_by_row[row_index], key=lambda c: c["column_index"])
            rows.append(
                {
                    "row_index": row_index,
                    "cells": row_cells,
                    "text": [c["text"] for c in row_cells],
                }
            )

        tables_output.append(
            {
                "table_index": table_idx,
                "row_count": int(getattr(table, "row_count", len(rows)) or len(rows)),
                "column_count": int(getattr(table, "column_count", 0) or 0),
                "rows": rows,
            }
        )

    return {
        "tables": tables_output,
        "page_count": len(getattr(result, "pages", []) or []),
    }
